// Simple masking example used in testing
function maskPII(value, field){
  if(!value) return null;
  switch(field){
    case 'ssn': return 'XXX-XX-' + value.slice(-4);
    case 'email': return '***@example.com';
    default: return 'REDACTED';
  }
}
